FUNCTION_BLOCK FB_S14
VAR_INPUT
    Pressure : REAL;
    PumpEnable : BOOL;
    ResetBtn : BOOL;
END_VAR
VAR_OUTPUT
    LowPump : BOOL := FALSE;
    HighPump : BOOL := FALSE;
    ReliefValve : BOOL := FALSE;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetBtnLast : BOOL := FALSE;
    HighPumpLatched : BOOL := FALSE;
    FaultLatched : BOOL := FALSE;
    ResetEdge : BOOL := FALSE;
    SensorFault : BOOL := FALSE;
END_VAR

(*
    扫描周期：20 ms。

    需求原文：
    液压站按系统压力自动投切泵组与卸荷阀，要求不频繁启停、
    越界立即保护。
    1. PumpEnable = TRUE 且 AlarmLamp = FALSE 时：
       Pressure < 120.0 bar，LowPump = TRUE。
    2. Pressure >= 140.0 bar，高压泵投入。
    3. 高压泵投入后，只有 Pressure < 100.0 bar 才断开；
       100.0 <= Pressure < 140.0 区间保持原状态。
    4. Pressure > 160.0 bar，卸荷阀打开，两泵停止；
       Pressure < 150.0 bar 后卸荷阀关闭。
    5. 卸荷阀与两泵互斥。
    6. Pressure < 0.5 bar 或 Pressure > 250.0 bar：
       两泵停止、报警、Status = 16#8D01。
       故障消失后需 ResetBtn 上升沿复位，复位前为 16#8D02。
    7. Status：16#0000 正常，16#8D01 故障，16#8D02 待复位。

    规约冲突记录（待审，不声称全部规约可同时满足）：
    - C10 要求上电首周期输出全部关闭且无报警，而 K1 要求
      过压同周期卸荷；首周期过压时两者不能同时满足。
      此实现将给定初态用于变量初始化，不屏蔽首周期安全保护。
    - C1/C2/C7 使用 X，文字要求包含同周期动作；
      若 X 表示下一次调用输出，则输入在相邻调用间变化时，
      不能无条件同时满足这些公式和即时安全保护。
    - K2 未排除故障。例如 Pressure < 0.5 且允许加载时，
      其加载要求与传感器故障停泵要求冲突。
    - C7 未排除撤销 PumpEnable、故障及卸荷；
      无条件保持可能与安全停泵冲突。
    - 第3条“只有低于100才断开”必须与第4、6条强制停泵
      区分；此实现安全停泵优先，并清除高压泵保持状态。

    实现优先级：传感器故障禁止泵运行；卸荷禁止泵运行；
    其次为允许加载与压力滞回。卸荷独立于泵允许和报警，
    因而 Pressure > 250.0 时仍打开卸荷阀。
    未经真实编译器及逐周期测试验证。
*)

(* 每次调用均更新边沿历史；故障期间的边沿不留待以后使用。 *)
ResetEdge := ResetBtn AND NOT ResetBtnLast;
ResetBtnLast := ResetBtn;

SensorFault := (Pressure < REAL#0.5) OR
               (Pressure > REAL#250.0);

(* 故障优先于复位；有效压力恢复后才接受新的复位上升沿。 *)
IF SensorFault THEN
    FaultLatched := TRUE;
ELSIF ResetEdge THEN
    FaultLatched := FALSE;
END_IF;

AlarmLamp := FaultLatched;

IF SensorFault THEN
    Status := WORD#16#8D01;
ELSIF FaultLatched THEN
    Status := WORD#16#8D02;
ELSE
    Status := WORD#16#0000;
END_IF;

(* 卸荷滞回：160恰好不触发，150恰好不解除。 *)
IF Pressure > REAL#160.0 THEN
    ReliefValve := TRUE;
ELSIF Pressure < REAL#150.0 THEN
    ReliefValve := FALSE;
END_IF;

(* 所有停泵条件优先于压力加载，保证阀泵互斥。 *)
IF AlarmLamp OR ReliefValve OR NOT PumpEnable THEN
    LowPump := FALSE;
    HighPump := FALSE;
    HighPumpLatched := FALSE;
ELSE
    LowPump := Pressure < REAL#120.0;

    IF Pressure >= REAL#140.0 THEN
        HighPumpLatched := TRUE;
    ELSIF Pressure < REAL#100.0 THEN
        HighPumpLatched := FALSE;
    END_IF;

    HighPump := HighPumpLatched;
END_IF;

END_FUNCTION_BLOCK
